Object.assign(window.TEM8_DICTIONARY, {"multitasking":{"media":{"uk":"media/uk/multitasking__gb_1.mp3","us":"media/us/multitasking__us_1.mp3"},"oxford":{"phon":"ˌmʌltiˈtɑːskɪŋ","pos":"noun","senses":[{"en":"the ability of a computer to operate several programs at the same time","cn":"多任务处理","lab":"computing"},{"en":"the ability to do several things at the same time","cn":"能同时处理多项事情的"}]},"examples":[{"en":"Women are traditionally supposed to be good at multitasking.","cn":"传统上认为女性善于同时做几件事情。"}]},"multiple":{"media":{"uk":"media/uk/multiple__gb_1.mp3","us":"media/us/multiple__us_1.mp3"},"oxford":{"phon":"ˈmʌltɪpl","pos":"adjective","senses":[{"en":"many in number; involving many different people or things","cn":"数量多的；多种多样的","ex":{"en":"The shape appears multiple times within each painting.","cn":"该图形在各幅画中都出现多次。"}},{"en":"complex in its nature or effects; affecting several parts of the body","cn":"多重的；多发性的","ex":{"en":"She suffered multiple injuries in the crash.","cn":"她在撞击中多处受伤。"}},{"en":"a quantity that contains another quantity an exact number of times","cn":"倍数","lab":"mathematics","ex":{"en":"14, 21 and 28 are all multiples of 7.","cn":"14、21 和 28 都是 7 的倍数。"},"pos":"noun"},{"en":"a shop that is one of a series of similar shops owned by the same company","cn":"连锁店","lab":"both British English, old-fashioned，，","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"多部分的;涉及多人的;有多种用途的","en":"You use multiple to describe things that consist of many parts, involve many people, or have many uses.","ex":{"en":"He died of multiple injuries","cn":"他死于多处受伤。"}},{"pos":"N-COUNT 可数名词","cn":"倍数","en":"If one number is a multiple of a smaller number, it can be exactly divided by that smaller number.","ex":{"en":"Their numerical system, derived from the Babylonians, was based on multiples of the number six.","cn":"他们的数制源自古巴比伦人，以数字6的倍数为基数。"}},{"pos":"N-COUNT 可数名词","cn":"连锁商店;连锁店","en":"A multiple or a multiple store is a shop with a lot of branches in different towns.","ex":{"en":"It made it almost impossible for the smaller retailer to compete against the multiples.","cn":"这使得小零售商几乎不可能跟连锁店竞争。"}}]},"examples":[{"en":"Traveller's cheques are available in multiples of €10 (= to the value of €10, €20, €30, etc.).","cn":"购买旅行支票以 10 欧元的倍数计算面值。"},{"en":"18 is the lowest common multiple of 6 and 9. * 18","cn":"是 6 和 9 的最小公倍数。"}]},"muslims":{"lemma":"muslim"},"muscular":{"media":{"uk":"media/uk/muscular__gb_1.mp3","us":"media/us/muscular__us_1.mp3"},"oxford":{"phon":"ˈmʌskjələ(r)","pos":"adjective","senses":[{"en":"relating to the muscles","cn":"肌肉的","ex":{"en":"muscular tension/power/tissue","cn":"肌肉张力／力量／组织"}},{"en":"having large strong muscles","cn":"强壮的；肌肉发达的","lab":"informal","ex":{"en":"a muscular body/build/chest","cn":"强壮的身体／体格；肌肉发达的胸部"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"肌肉的;影响肌肉的","en":"Muscular means involving or affecting your muscles.","ex":{"en":"As a general rule, all muscular effort is enhanced by breathing in as the effort is made","cn":"通常，肌肉的力量能通过使劲儿吸气增强。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肌肉结实的;强壮的","en":"If a person or their body is muscular, they are very fit and strong, and have firm muscles which are not covered with a lot of fat.","ex":{"en":"Like most female athletes, she was lean and muscular.","cn":"像大多女运动员一样，她清瘦但肌肉发达。"}}]},"examples":[{"en":"He was tall, lean and muscular.","cn":"他高挑瘦削，强壮有力。"},{"en":"a muscular body/build/chest","cn":"强壮的身体/体格；肌肉发达的胸部"}]},"much":{"media":{"uk":"media/uk/much__gb_1.mp3","us":"media/us/much__us_1.mp3"},"oxford":{"phon":"mʌtʃ","pos":"determiner, pronoun","senses":[{"en":"used with uncountable nouns, especially in negative sentences to mean ‘a large amount of something’, or after ‘how’ to ask about the amount of something. It is also used with ‘as’, ‘so’ and ‘too’.","cn":"（与不可数名词连用，尤用于否定句；或与 how 连用以询问数量；也可与 as、so 和 too 连用）许多，大量","lab":"formal","ex":{"en":"I don't have much money with me.","cn":"我没带多少钱。"}},{"en":"to a great degree","cn":"非常；十分；很","lab":"British English","ex":{"en":"Thank you very much for the flowers.","cn":"非常感谢你的这些花。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"(表示行动、感情或变化的强烈程度，通常和 so，too，very 一起用于否定句中)很多，非常","en":"You use much to indicate the great intensity, extent, or degree of something such as an action, feeling, or change. Much is usually used with 'so', 'too', and 'very', and in negative clauses with this meaning.","ex":{"en":"She laughs too much","cn":"她笑得太多了。"}},{"pos":"ADV-GRADED 副词","cn":"经常;常常","en":"If something does not happen much, it does not happen very often.","ex":{"en":"He said that his father never talked much about the war","cn":"他说他父亲从来不多谈那场战争。"}},{"pos":"ADV-GRADED 副词","cn":"(置于比较级或 too 前，表示强调)太，很","en":"You use much in front of 'too' or comparative adjectives and adverbs in order to emphasize that there is a large amount of a particular quality.","ex":{"en":"The skin is much too delicate","cn":"皮肤太娇嫩了。"}},{"pos":"ADV 副词","cn":"很大程度上","en":"If one thing is much the same as another thing, it is very similar to it.","ex":{"en":"The day ended much as it began","cn":"这一天的开始和结束几乎是一样的。"}},{"pos":"DET 限定词","cn":"许多；大量","en":"You use much to indicate that you are referring to a large amount of a substance or thing.","ex":{"en":"They are grown on the hillsides in full sun, without much water","cn":"它们被种植在阳光充足、土壤水分不多的山坡上。"}},{"pos":"ADV-GRADED 副词","cn":"(用于回答关于数量的提问)不多/不太多/太多","en":"You use much in expressions such as not much ,not very much, and too much when replying to questions about amounts.","ex":{"en":"'Can you hear it where you live?' He shook his head. 'Not much.'","cn":"“你住的地方听得到吗？”他摇摇头说：“很少听到。”"}},{"pos":"QUANT 数量词","cn":"常常;多次","en":"If you do not see much of someone, you do not see them very often.","ex":{"en":"I don't see much of Tony nowadays","cn":"我现在见托尼的次数不多。"}},{"pos":"DET 限定词","cn":"多少(用于对数量的询问或说明)","en":"You use much in the expression how much to ask questions about amounts or degrees, and also in reported clauses and statements to give information about the amount or degree of something.","ex":{"en":"How much money can I afford?","cn":"我能出得起多少钱？"}},{"pos":"DET 限定词","cn":"(用于比较数量)同样多","en":"You use much in the expression as much when you are comparing amounts.","ex":{"en":"I shall try, with as much patience as is possible, to explain yet again","cn":"我会尽可能耐心地试着再解释一遍。"}},{"pos":"PHR-CONJ-SUBORD","cn":"虽然;尽管","en":"You use much as to introduce a fact which makes something else you have just said or will say rather surprising.","ex":{"en":"Much as they hope to go home tomorrow, they're resigned to staying on until the end of the year.","cn":"虽然他们希望明天就回家，但还是准备耐心地继续呆到年底。"}},{"pos":"PHRASE 短语","cn":"我想/ 我猜也是这样","en":"You use as much in expressions such as 'I thought as much' and 'I guessed as much' after you have just been told something and you want to say that you already believed or expected it to be true.","ex":{"en":"You're waiting for a woman — I thought as much.","cn":"你在等一位女士——我也这么想的。"}},{"pos":"PHRASE 短语","cn":"(置于数量前)多达","en":"You use as much as before an amount to suggest that it is surprisingly large.","ex":{"en":"The organisers hope to raise as much as £6m for charity.","cn":"组织者希望能募集到高达600万英镑的善款。"}},{"pos":"PHRASE 短语","cn":"更不用说；更何况","en":"You use much less after a statement, often a negative one, to indicate that the statement is more true of the person, thing, or situation that you are going to mention next.","ex":{"en":"They are always short of water to drink, much less to bathe in","cn":"他们的饮用水一直短缺，更别提洗澡水了。"}},{"pos":"PHRASE 短语","cn":"没什么;不重要","en":"You say nothing much to refer to something that is not very interesting or important.","ex":{"en":"'What was stolen?' — 'Oh, nothing much.'","cn":"“什么被偷了？”——“噢，不是什么重要的东西。”"}},{"pos":"PHRASE 短语","cn":"不太好的；称不上…的","en":"If you describe something as not much of a particular type of thing, you mean that it is small or of poor quality.","ex":{"en":"It hasn't been much of a holiday","cn":"这简直不像是假日。"}},{"pos":"PHRASE 短语","cn":"就讲这么多；到此为止","en":"So much for is used to indicate that you have finished talking about a subject.","ex":{"en":"Well, so much for the producers. But what of the con-sumers?","cn":"好吧，关于生产商就讲这么多，那关于消费者呢？"}},{"pos":"PHRASE 短语","cn":"不过如此；没有益处","en":"If you say so much for a particular thing, you mean that it has not been successful or helpful.","ex":{"en":"He has spent 19 million pounds, lost three cup finals and been relegated. So much for money.","cn":"他已花了1,900万英镑，输掉了三场杯赛决赛，球队也降级了。钱也不是万能的。"}},{"pos":"PHRASE 短语","cn":"与其说是…不如说是…","en":"If you say that something is not so much one thing as another, you mean that it is more like the second thing than the first.","ex":{"en":"I don't really think of her as a daughter so much as a very good friend","cn":"与其说我把她当作女儿，不如说把她当作好朋友。"}},{"pos":"PHRASE 短语","cn":"甚至;竟然","en":"If you say that someone did not do so much as perform a particular action, you are emphasizing that they did not even do that, when you were expecting them to do more.","ex":{"en":"I didn't so much as catch sight of him all day long","cn":"我一整天都没见他人影。"}},{"pos":"PHRASE 短语","cn":"太…以至于…","en":"You use so much so to indicate that your previous statement is true to a very great extent, and therefore it has the result mentioned.","ex":{"en":"He himself believed in freedom, so much so that he would rather die than live without it.","cn":"他非常崇尚自由，不自由，毋宁死。"}},{"pos":"PHRASE 短语","cn":"非…力所能及的;非…应付得了的","en":"If a situation or action is too much for you, it is so difficult, tiring, or upsetting that you cannot cope with it.","ex":{"en":"His inability to stay at one job for long had finally proved too much for her.","cn":"他没有哪份工作能干长，这一点最终让她难以忍受。"}},{"pos":"PHRASE 短语","cn":"非常;确实","en":"You use very much to emphasize that someone or something has a lot of a particular quality, or that the description you are about to give is particularly accurate.","ex":{"en":"...a man very much in charge of himself","cn":"自制力很强的人"}},{"pos":"","cn":"","en":"a bit much→see: ; not up to much→see: ;"}]},"examples":[{"en":"Please help me get this job — you know I would do as much for you.","cn":"请帮我弄到这份工作，你知道我也会为你的事同样尽力。"},{"en":"No dessert for me, thanks. It was as much as I could do to finish the main course.","cn":"谢谢，别给我甜食了。我吃完这道主菜就不错了。"}]},"multi-purpose":{"oxford":{"phon":"","pos":"adj.","senses":[{"en":"able to be used for several different purposes","cn":"多用途的；多功能的"}]},"media":{"uk":"media/uk/multi_purpose_1_gb_1.mp3","us":"media/us/multi_purpose_1_us_1.mp3"},"examples":[{"en":"a multi-purpose tool/machine","cn":"多用途工具；多功能机"}]},"mutual":{"media":{"uk":"media/uk/mutual__gb_1.mp3","us":"media/us/mutual__us_1.mp3"},"oxford":{"phon":"ˈmjuːtʃuəl","pos":"adjective","senses":[{"en":"used to describe feelings that two or more people have for each other equally, or actions that affect two or more people equally","cn":"相互的；彼此的","ex":{"en":"mutual respect/understanding","cn":"相互的尊敬／理解"}},{"en":"shared by two or more people","cn":"共有的；共同的","g":"[only before noun]","ex":{"en":"We met at the home of a mutual friend.","cn":"我们在彼此都认识的朋友家中会面。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相互的;彼此的","en":"You use mutual to describe a situation, feeling, or action that is experienced, felt, or done by both of two people mentioned.","ex":{"en":"The East and the West can work together for their mutual benefit and progress","cn":"东西方可以为彼此共同的利益和发展而合作。"}},{"pos":"ADJ 形容词","cn":"共同的;共有的","en":"You use mutual to describe something such as an interest which two or more people share.","ex":{"en":"They do, however, share a mutual interest in design","cn":"不过他们确实都对设计感兴趣。"}},{"pos":"ADJ 形容词","cn":"(指建屋互助会或保险公司)互助的，相互保险的","en":"If a building society or an insurance company has mutual status, it is not owned by shareholders but by its customers, who receive a share of the profits.","ex":{"en":"Britain's third largest building society abandoned its mutual status and became a bank.","cn":"英国第三大建屋互助会准备放弃其互助性质，转变为银行。"}}]},"examples":[{"en":"They soon discovered a mutual interest in music.","cn":"他们很快发现对音乐有着共同的兴趣。"},{"en":"I don't like her, and I think the feeling is mutual (= she doesn't like me either).","cn":"我不喜欢她，我觉得她也不喜欢我。"}]},"museum":{"media":{"uk":"media/uk/museum__gb_1.mp3","us":"media/us/museum__us_1.mp3"},"oxford":{"phon":"mjuˈziːəm","pos":"noun","senses":[{"en":"a building in which objects of artistic, cultural, historical or scientific interest are kept and shown to the public","cn":"博物馆","ex":{"en":"a museum of modern art","cn":"现代艺术博物馆"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"博物馆;博物院","en":"A museum is a building where a large number of interest-ing and valuable objects, such as works of art or historical items, are kept, studied, and displayed to the public.","ex":{"en":"For months Malcolm had wanted to visit the Parisian art museums.","cn":"几个月来马尔科姆一直想参观巴黎的艺术博物馆。"}}]},"examples":[{"en":"a museum of modern art","cn":"现代艺术博物馆"},{"en":"a science museum","cn":"科学博物馆"}]},"muhammad":{"oxford":{"phon":"məˈhæmɪd","pos":"noun","senses":[{"en":"the Arab Prophet through whom the Koran was revealed and the religion of Islam established and completed","cn":"穆罕默德（阿拉伯的先知、伊斯兰教的创立人）"},{"en":"a first name for boys","cn":"穆罕默德（男子名）"}]},"media":{"uk":"media/uk/muhammad__gb_1.mp3","us":"media/us/muhammad__us_1.mp3"}},"mud":{"oxford":{"phon":"mʌd","pos":"noun","senses":[{"en":"wet earth that is soft and sticky","cn":"泥；淤泥；泥浆","lab":"especially North American English","ex":{"en":"The car wheels got stuck in the mud.","cn":"汽车轮子陷到泥里去了。"}},{"en":"a computer game played over the internet by several players at the same time (the abbreviation for ‘multi-user dungeon’ or ‘multi-user dimension’)","cn":"“泥巴” 游戏，多用户网络游戏（全写为 multi-user dungeon/dimension）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"泥;烂泥;泥浆","en":"Mud is a sticky mixture of earth and water.","ex":{"en":"His uniform was crumpled, untidy, splashed with mud","cn":"他的制服皱巴巴的，邋遢不堪，还溅上了泥点。"}}]},"media":{"uk":"media/uk/mud__gb_1.mp3","us":"media/us/mud__us_1.mp3"},"examples":[{"en":"The car wheels got stuck in the mud.","cn":"汽车轮子陷到泥里去了。"},{"en":"Your boots are covered in mud.","cn":"你的靴子上都是泥。"}]},"murky":{"media":{"uk":"media/uk/murky__gb_1.mp3","us":"media/us/murky__us_1.mp3"},"oxford":{"phon":"ˈmɜːki","pos":"adjective","senses":[{"en":"not clear; dark or dirty with mud or another substance","cn":"浑浊的；污浊的","lab":"figurative","ex":{"en":"She gazed into the murky depths of the water.","cn":"她注视着那幽暗的水底。"}},{"en":"dark and unpleasant because of smoke, fog, etc.","cn":"昏暗的；阴暗的；朦胧的","ex":{"en":"a murky night","cn":"昏暗的夜"}},{"en":"not clearly known and suspected of not being honest","cn":"隐晦的；含糊的；暧昧可疑的","lab":"disapproving or humorous","ex":{"en":"He had a somewhat murky past.","cn":"他有一段不清白的过去。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阴暗的;昏暗的","en":"A murky place or time of day is dark and rather unpleasant because there is not enough light.","ex":{"en":"The large lamplit room was murky with woodsmoke","cn":"木柴冒出的烟把亮着灯的大房间弄得烟雾弥漫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(水或雾)污浊的，浑浊的","en":"Murky water or fog is so dark and dirty that you cannot see through it.","ex":{"en":"...the deep, murky waters of Loch Ness.","cn":"内斯湖幽深浑浊的湖水"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暧昧可疑的;不可告人的","en":"If you describe an activity or situation as murky, you suspect that it is dishonest or morally wrong.","ex":{"en":"There has been a murky conspiracy to keep them out of power.","cn":"有人策划了一个不可告人的阴谋要将他们排斥在权力中心之外。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含糊不清的;难以理解的","en":"If you describe something as murky, you mean that the details of it are not clear or that it is difficult to understand.","ex":{"en":"The law here is a little bit murky","cn":"此处的法律条文有点含糊不清。"}}]},"examples":[{"en":"She gazed into the murky depths of the water.","cn":"她注视着那幽暗的水底。"},{"en":"He had a somewhat murky past.","cn":"他有一段不清白的过去。"}]},"must":{"media":{"uk":"media/uk/must__gb_1.mp3","us":"media/us/must__us_1.mp3"},"oxford":{"phon":"məst","pos":"modal verb","senses":[{"en":"used to say that something is necessary or very important (sometimes involving a rule or a law)","cn":"（表示必要或很重要）必须","lab":"formal","ex":{"en":"All visitors must report to reception.","cn":"所有访客必须到接待处报到。"}},{"en":"used to say that something is likely or logical","cn":"（表示很可能或符合逻辑）一定","lab":"North American English","ex":{"en":"You must be hungry after all that walking.","cn":"走了这么远的路，你一定饿了吧。"}},{"en":"used to recommend that somebody does something because you think it is a good idea","cn":"（提出建议）应该，得","lab":"especially British English","ex":{"en":"You simply must read this book.","cn":"这本书你可一定要看一看。"}},{"en":"something that you must do, see, buy, etc.","cn":"必须做（或看、买等）的事","ex":{"en":"His new novel is a must for all lovers of crime fiction.","cn":"他的新作是所有犯罪小说爱好者的必读书。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"MODAL 情态动词","cn":"必须；一定要","en":"You use must to indicate that you think it is very important or necessary for something to happen. You use must not or mustn't to indicate that you think it is very important or necessary for something not to happen.","ex":{"en":"What you wear should be stylish and clean, and must definitely fit well","cn":"你的穿着应该整洁漂亮，而且必须非常合身。"}},{"pos":"MODAL 情态动词","cn":"(通常因为规定或法律)必须，应当","en":"You use must to indicate that it is necessary for something to happen, usually because of a rule or law.","ex":{"en":"Candidates must satisfy the general conditions for admission","cn":"候选人必须满足参选的总体条件。"}},{"pos":"MODAL 情态动词","cn":"(用于表示肯定推测)一定，谅必","en":"You use must to indicate that you are fairly sure that something is the case.","ex":{"en":"At 29 Russell must be one of the youngest ever Wembley referees","cn":"29岁的拉赛尔一定是有史以来温布利球场上的裁判员中最年轻的一个。"}},{"pos":"MODAL 情态动词","cn":"(用于表示据已知情况推测)很可能是，想必是，肯定是","en":"You use must, or must have with a past participle, to indicate that you believe that something is the case, because of the available evidence.","ex":{"en":"'You must be Emma,' said the visitor","cn":"来客说：“你肯定是埃玛。”"}},{"pos":"MODAL 情态动词","cn":"(用于表示前者为后者的前提)应该已经(发生)","en":"If you say that one thing must have happened in order for something else to happen, you mean that it is necessary for the first thing to have happened before the second thing can happen.","ex":{"en":"In order to take that job, you must have left another job","cn":"为得到那份工作，你肯定已辞去了另一份工作。"}},{"pos":"MODAL 情态动词","cn":"(用于表示意图)一定要，坚持要","en":"You use must to express your intention to do something.","ex":{"en":"I must be getting back","cn":"我一定要回来。"}},{"pos":"MODAL 情态动词","cn":"(用于表示建议或邀请)务必，一定要","en":"You use must to make suggestions or invitations very forcefully.","ex":{"en":"You must see a doctor, Frederick","cn":"弗雷德里克，你一定得去看医生。"}},{"pos":"MODAL 情态动词","cn":"(用于表示同情)必定，想必","en":"You use must in remarks and comments where you are expressing sympathy.","ex":{"en":"This must be a very difficult job for you","cn":"对你来说，这份工作想必很难。"}},{"pos":"MODAL 情态动词","cn":"(用于强调)我得说/我得承认","en":"You use must in conversation in expressions such as 'I must say' and 'I must admit' in order to emphasize a point that you are making.","ex":{"en":"This came as a surprise, I must say","cn":"我得说这真是个意外。"}},{"pos":"MODAL 情态动词","cn":"(用于引起读者或听众的注意)一定要注意/一定记住","en":"You use must in expressions such as 'it must be noted' and 'it must be remembered' in order to draw the reader's or listener's attention to what you are about to say.","ex":{"en":"It must be noted, however, that not all British and American officers carried out orders","cn":"然而，一定要注意不是所有的英国和美国军官都执行了命令。"}},{"pos":"MODAL 情态动词","cn":"(用于问句中表示生气)偏偏，非要","en":"You use must in questions to express your anger or irritation about something that someone has done, usually because you do not understand their behaviour.","ex":{"en":"Why must you do everything as if you have to win?","cn":"你为什么做每件事情都跟你非要赢似的？"}},{"pos":"MODAL 情态动词","cn":"(用于感叹句，表示惊讶或震惊)一定是，准是","en":"You use must in exclamations to express surprise or shock.","ex":{"en":"'Go! Please go.' — 'You must be joking!'","cn":"“走吧！请走吧。”——“你一定是在开玩笑吧！”"}},{"pos":"N-COUNT 可数名词","cn":"必不可少的事物;一定要做的事","en":"If you refer to something as a must, you mean that it is absolutely necessary.","ex":{"en":"The new 37th issue of National Savings Certificates is a must for any taxpayer","cn":"新发行的第37期国家储蓄债券是任何一个纳税人的必然之选。"}},{"pos":"PHRASE 短语","cn":"如果你一定要(这样做的话)","en":"You say 'if you must' when you know that you cannot stop someone doing something that you think is wrong or stupid.","ex":{"en":"If you must be in the sunlight, use the strongest filter cream you can get","cn":"如果一定要呆在太阳底下的话，就擦上你能买到的防晒系数最高的防晒霜。"}},{"pos":"PHRASE 短语","cn":"如果你一定想要知道的话","en":"You say 'if you must know' when you tell someone something that you did not want them to know and you want to suggest that you think they were wrong to ask you about it.","ex":{"en":"'Why don't you wear your jogging shorts Mum?' — 'Well, my legs are too skinny, if you must know.'","cn":"“妈妈，为什么不穿你的慢跑短裤呢？”——“哦，如果你非要问的话，因为我的腿太瘦了。”"}}]},"examples":[{"en":"‘Do we have to finish this today?’ ‘Yes, you must.’ “","cn":"我们今天一定得完成这工作吗？” “对，必须完成。”"},{"en":"‘Can I smoke?’ ‘If you must.’ “","cn":"我可以抽烟吗？” “好吧，如果你非要的话。”"}]},"murder":{"media":{"uk":"media/uk/murder__gb_1.mp3","us":"media/us/murder__us_1.mp3"},"oxford":{"phon":"ˈmɜːdə(r)","pos":"noun","senses":[{"en":"the crime of killing somebody deliberately","cn":"谋杀；凶杀","g":"[uncountable, countable]","lab":"British English","ex":{"en":"He was found guilty of murder.","cn":"经裁决，他犯有谋杀罪。"}},{"en":"used to describe something that is difficult or unpleasant","cn":"困难的事；讨厌的事","g":"[uncountable]","lab":"informal","ex":{"en":"It's murder trying to get to the airport at this time of day.","cn":"这个时候要赶到机场简直要命。"}},{"en":"to kill somebody deliberately and illegally","cn":"谋杀；凶杀","ex":{"en":"He denies murdering his wife's lover.","cn":"他否认谋杀了妻子的情人。"},"pos":"verb"},{"en":"to change something good into something bad because you do not do it very well","cn":"糟蹋；毁坏；弄坏","ex":{"en":"Critics accused him of murdering the English language (= writing or speaking it very badly).","cn":"批评家指责他把英语给糟蹋了。"},"pos":"verb"},{"en":"to defeat somebody completely, especially in a team sport","cn":"（尤指在团队运动中）彻底打败，打垮","lab":"informal","ex":{"en":"England are getting murdered at the moment.","cn":"英格兰此刻正在被谋杀。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"谋杀;杀害;凶杀","en":"Murder is the deliberate and illegal killing of a person. →see usage note at:","ex":{"en":"The three accused, aged between 19 and 20, are charged with attempted murder","cn":"3个年龄在19到20岁之间的被告被控谋杀未遂。"}},{"pos":"VERB 动词","cn":"谋杀;杀害","en":"To murder someone means to commit the crime of killing them deliberately.","ex":{"en":"...a thriller about two men who murder a third to see if they can get away with it.","cn":"关于两个男人为了看看是否能成功逃脱惩罚而去谋杀另一名男子的惊悚片"}},{"pos":"PHRASE 短语","cn":"(做坏事而)安然无恙，逍遥法外，为所欲为","en":"If you say that someone gets away with murder, you are complaining that they can do whatever they like without anyone trying to control them or punish them.","ex":{"en":"His charm and the fact that he is so likeable often allows him to get away with murder.","cn":"他很有魅力而且讨人喜欢，这常让他能够为所欲为。"}},{"pos":"PHRASE 短语","cn":"(对不喜欢的东西)大惊小怪地拼命叫嚷","en":"If you say that someone screams blue murder or screams bloody murder, you are emphasizing that they are making a lot of noise or fuss about something that they do not like.","ex":{"en":"People are screaming blue murder about the amount of traffic going through their town.","cn":"人们对着那些穿越他们城市的川流不息的车辆大呼小叫。"}}]},"examples":[{"en":"The rebels were responsible for the mass murder of 400 civilians.","cn":"叛乱者对屠杀 400 名平民负有责任。"},{"en":"The murdered woman was well known in the area.","cn":"被杀害的女人在这个地区很有名气。"}]},"muted":{"oxford":{"phon":"ˈmjuːtɪd","pos":"adjective","senses":[{"en":"quiet; not as loud as usual","cn":"静静的；减轻的","ex":{"en":"the muted sound of traffic outside","cn":"外面低沉的交通声"}},{"en":"not strongly expressed","cn":"含糊不清的；表达不明确的","ex":{"en":"The proposals received only a muted response.","cn":"这个倡议没有得到明确的回应。"}},{"en":"not bright","cn":"暗淡的；不明亮的","ex":{"en":"She wore a dress in muted shades of blue.","cn":"她穿着一件柔和的蓝色连衣裙。"}},{"en":"used with a mute","cn":"使用弱音器的","ex":{"en":"muted trumpets","cn":"装有弱音器的小号"}},{"en":"with the sound turned off","cn":"设为静音的","ex":{"en":"She glanced at the captions on the muted TV.","cn":"她看了一眼静音电视上的字幕。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色)柔和的，不鲜艳的","en":"Muted colours are soft and gentle, not bright and strong.","ex":{"en":"He likes sombre, muted colours — she likes bright colours","cn":"他喜欢暗淡、柔和的颜色;而她喜欢明艳的颜色。"}}]},"media":{"uk":"media/uk/muted__gb_1.mp3","us":"media/us/muted__us_1.mp3"},"examples":[{"en":"The proposals received only a muted response.","cn":"这个倡议没有得到明确的回应。"},{"en":"They spoke in muted voices.","cn":"他们轻声说着话。"}],"base":"mute"},"musical":{"media":{"uk":"media/uk/musical__gb_1.mp3","us":"media/us/musical__us_1.mp3"},"oxford":{"phon":"ˈmjuːzɪkl","pos":"adjective","senses":[{"en":"connected with music; containing music","cn":"音乐的；有音乐的","g":"[only before noun]","ex":{"en":"musical styles/tastes","cn":"音乐风格／品味"}},{"en":"with a natural skill or interest in music","cn":"有音乐天赋的；喜爱音乐的","ex":{"en":"She's very musical.","cn":"她极具音乐天赋。"}},{"en":"pleasant to listen to, like music","cn":"悦耳的；音乐般的","ex":{"en":"a musical voice","cn":"悦耳的声音"}},{"en":"a play or film in which part or all of the story is told using songs and often dancing","cn":"音乐剧；歌舞片","ex":{"en":"a Broadway/Hollywood musical","cn":"百老汇/好莱坞音乐剧"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"音乐的;与音乐有关的","en":"You use musical to indicate that something is connected with playing or studying music.","ex":{"en":"We have a wealth of musical talent in this region","cn":"在这一地区有大量的音乐人才。"}},{"pos":"N-COUNT 可数名词","cn":"音乐剧;音乐歌舞片","en":"A musical is a play or film that uses singing and dancing in the story.","ex":{"en":"...London's smash hit musical Miss Saigon.","cn":"在伦敦轰动一时的音乐剧《西贡小姐》"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有音乐天赋的;喜爱音乐的","en":"Someone who is musical has a natural ability and interest in music.","ex":{"en":"I came from a musical family.","cn":"我出身于音乐世家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好听的;悦耳的","en":"Sounds that are musical are light and pleasant to hear.","ex":{"en":"He had a soft, almost musical voice.","cn":"他声音柔和，如音乐般动听。"}}]},"examples":[{"en":"the musical director of the show","cn":"这场演出的音乐指导"},{"en":"She's very musical.","cn":"她极具音乐天赋。"}]},"muslim":{"oxford":{"phon":"ˈmʊzlɪm","pos":"adjective","senses":[{"en":"believing in and practising Islam; connected with the religion of Islam","cn":"（与）穆斯林（有关）的；（与）伊斯兰教（有关）的","ex":{"en":"a Muslim family","cn":"信伊斯兰教的家庭"}},{"en":"a person whose religion is Islam","cn":"穆斯林；伊斯兰教信徒","ex":{"en":"This festival is celebrated by Muslims around the world.","cn":"世界各地的穆斯林庆祝这个节日。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"穆斯林;伊斯兰教信徒","en":"A Muslim is someone who believes in Islam and lives according to its rules."},{"pos":"ADJ 形容词","cn":"穆斯林的;伊斯兰教的","en":"Muslim means relating to Islam or Muslims.","ex":{"en":"...Iran and other Muslim countries.","cn":"伊朗和其他伊斯兰国家"}}]},"media":{"uk":"media/uk/muslim__gb_1.mp3","us":"media/us/muslim__us_1.mp3"}},"multitude":{"media":{"uk":"media/uk/multitude__gb_1.mp3","us":"media/us/multitude__us_1.mp3"},"oxford":{"phon":"ˈmʌltɪtjuːd","pos":"noun","senses":[{"en":"an extremely large number of things or people","cn":"众多；大量","g":"[countable]","ex":{"en":"a multitude of possibilities","cn":"众多的可能性"}},{"en":"the mass of ordinary people","cn":"群众；大批百姓；民众","g":"[singular + singular or plural verb]","lab":"sometimes disapproving","ex":{"en":"It was an elite that believed its task was to enlighten the multitude.","cn":"精英人物会认为自己的职责是启迪群众。"}},{"en":"a large crowd of people","cn":"人群","g":"[countable]","lab":"literary","ex":{"en":"He preached to the assembled multitude.","cn":"他向聚集在那里的民众布道。"}}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"许多;大量;大批;大群","en":"A multitude of things or people is a very large number of them.","ex":{"en":"There are a multitude of small quiet roads to cycle along","cn":"有很多可以骑车的宁静小路。"}},{"pos":"N-COUNT 可数名词","cn":"一大群人;人群","en":"You can refer to a very large number of people as a multitude .","ex":{"en":"...surrounded by a noisy multitude.","cn":"被喧闹的人群围着"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"民众；大众；群众","en":"You can refer to the great majority of people in a particular country or situation as the multitude or the multitudes .","ex":{"en":"The hideous truth was hidden from the multitude","cn":"向大众隐瞒了骇人听闻的真相。"}}]},"examples":[{"en":"These elements can be combined in a multitude of different ways.","cn":"这些因素可以通过无数不同的方式进行组合。"},{"en":"It was an elite that believed its task was to enlighten the multitude.","cn":"精英阶层会认为自己的职责是启迪群众。"}]},"murmur":{"media":{"uk":"media/uk/murmur__gb_1.mp3","us":"media/us/murmur__us_1.mp3"},"oxford":{"phon":"ˈmɜːmə(r)","pos":"verb","senses":[{"en":"to say something in a soft quiet voice that is difficult to hear or understand","cn":"低语；喃喃细语","g":"[transitive, intransitive]","ex":{"en":"She murmured her agreement.","cn":"她低声表示同意。"}},{"en":"to make a quiet continuous sound","cn":"连续发出低沉的声音","g":"[intransitive]","ex":{"en":"The wind murmured in the trees.","cn":"风在树林中沙沙作响。"}},{"en":"to complain about somebody/something, but not openly","cn":"（私下）发怨言，发牢骚","g":"[intransitive]","lab":"literary","ex":{"en":"The people murmured against the new regime.","cn":"人民怨声载道，反对新政权。"}},{"en":"a quietly spoken word or words","cn":"低语；喃喃声","g":"[countable]","ex":{"en":"She answered in a faint murmur.","cn":"她低声应答。"},"pos":"noun"},{"en":"a quiet expression of feeling","cn":"嘟囔；咕哝","g":"[countable]","ex":{"en":"a murmur of agreement/approval/complaint","cn":"表示同意／赞同／抱怨的低语声"},"pos":"noun"},{"en":"a low continuous sound in the background","cn":"接连从远处传来的低沉的声音","g":"[singular]","ex":{"en":"the distant murmur of traffic","cn":"远处传来的车辆的嘈杂声"},"pos":"noun"},{"en":"a very quiet sound in the chest, usually a sign of damage or disease in the heart","cn":"（心脏）杂音","g":"[countable]","lab":"medical","ex":{"en":"a heart murmur","cn":"心脏杂音"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"低声说;悄声说","en":"If you murmur something, you say it very quietly, so that not many people can hear what you are saying.","ex":{"en":"He turned and murmured something to the professor","cn":"他转身对教授小声说了些什么。"}},{"pos":"N-COUNT 可数名词","cn":"低语;咕哝;喃喃细语","en":"A murmur is something that is said which can hardly be heard.","ex":{"en":"They spoke in low murmurs","cn":"他们低声说着话。"}},{"pos":"N-SING 单数名词","cn":"(流水的）汩汩声；（远处）模糊的低语声","en":"A murmur is a continuous low sound, like the noise of a river or of voices far away.","ex":{"en":"The piano music mixes with the murmur of conversation","cn":"钢琴的弹奏声混杂着低低的交谈声。"}},{"pos":"N-COUNT 可数名词","cn":"低语表达;嘟囔","en":"A murmur of a particular emotion is a quiet expression of it.","ex":{"en":"The promise of some basic working rights draws murmurs of approval","cn":"对一些基本工作权利的承诺引来一片低声的赞许。"}},{"pos":"N-COUNT 可数名词","cn":"(心脏的) 杂音","en":"A murmur is an abnormal sound which is made by the heart and which shows that there is probably something wrong with it.","ex":{"en":"The doctor said James had now developed a heart murmur.","cn":"医生说詹姆斯的心脏有杂音。"}},{"pos":"PHRASE 短语","cn":"毫无怨言;没有微词","en":"If someone does something without a murmur, they do it without complaining."}]},"examples":[{"en":"Murmurs of ‘Praise God’ went around the circle.","cn":"周围的人群发出了“赞美主”的低语声。"},{"en":"He paid the extra cost without a murmur (= without complaining at all).","cn":"他一声不吭地付了额外的费用。"}]},"mu":{"oxford":{"phon":"mjuː","pos":"noun","senses":[{"en":"the 12th letter of the Greek alphabet (M, μ)","cn":"希腊字母表的第 12 个字母"}]},"media":{"uk":"media/uk/mu__gb_1.mp3","us":"media/us/mu__us_1.mp3"}},"musket":{"media":{"uk":"media/uk/musket__gb_1.mp3","us":"media/us/musket__us_1.mp3"},"oxford":{"phon":"ˈmʌskɪt","pos":"noun","senses":[{"en":"an early type of long gun that was used by soldiers in the past","cn":"（旧时的）火枪，滑膛枪，毛瑟枪"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滑膛枪；火枪","en":"A musket was an early type of gun with a long barrel, which was used before rifles were invented."}]}},"music":{"media":{"img":["media/pic/musicalnotation.jpg","media/thumb/quaver.jpg"],"uk":"media/uk/music__gb_1.mp3","us":"media/us/music__us_1.mp3"},"oxford":{"phon":"ˈmjuːzɪk","pos":"noun","senses":[{"en":"sounds that are arranged in a way that is pleasant or exciting to listen to. People sing music or play it on instruments.","cn":"音乐；乐曲","lab":"British English","ex":{"en":"I like any kind of pop or dance music.","cn":"我喜欢任何类型的流行音乐或舞曲。"}},{"en":"the art of writing or playing music","cn":"音乐创作；演奏艺术","ex":{"en":"He studied music in Moscow.","cn":"他曾在莫斯科学习音乐。"}},{"en":"the written or printed signs that represent the sounds to be played or sung in a piece of music","cn":"乐谱","ex":{"en":"Can you read music (= understand the signs in order to play or sing a piece of music)?","cn":"你识谱吗？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"音乐;乐曲","en":"Music is the pattern of sounds produced by people singing or playing instruments.","ex":{"en":"...classical music.","cn":"古典音乐"}},{"pos":"N-UNCOUNT 不可数名词","cn":"音乐(创作或表演)艺术","en":"Music is the art of creating or performing music.","ex":{"en":"He went on to study music, specialising in the clarinet.","cn":"他继续学习音乐，主攻单簧管。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"乐谱","en":"Music is the symbols written on paper which represent musical sounds.","ex":{"en":"He's never been able to read music.","cn":"他一直都不识谱。"}},{"pos":"PHRASE 短语","cn":"悦耳的声音;佳音;中听的话","en":"If something that you hear is music to your ears, it makes you feel very happy.","ex":{"en":"Popular support—it's music to the ears of any politician.","cn":"大众的支持对任何一名政界人士来说都是佳音。"}},{"pos":"PHRASE 短语","cn":"承担自己行为的后果;接受批评（或惩罚）","en":"If you face the music, you put yourself in a position where you will be criticized or punished for something you have done.","ex":{"en":"Sooner or later, I'm going to have to face the music.","cn":"迟早我得自己承担后果。"}}]},"examples":[{"en":"He wrote the music but I don't know who wrote the words.","cn":"他创作了乐曲，但我不知道谁填写的歌词。"},{"en":"Every week they get together to make music (= to play music or sing).","cn":"每个星期他们都聚在一起唱歌奏乐。"}]},"mutton":{"oxford":{"phon":"ˈmʌtn","pos":"noun","senses":[{"en":"meat from a fully grown sheep","cn":"羊肉"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"羊肉","en":"Mutton is meat from an adult sheep that is eaten as food.","ex":{"en":"...a leg of mutton.","cn":"羊腿"}},{"pos":"PHRASE 短语","cn":"装嫩的女人","en":"If you describe a woman as mutton dressed as lamb, you are criticizing her for trying to look younger than she really is, in a way that you consider unattractive."}]},"media":{"uk":"media/uk/mutton__gb_1.mp3","us":"media/us/mutton__us_1.mp3"}},"murders":{"lemma":"murder","media":{"uk":"media/uk/murder__gb_1.mp3","us":"media/us/murder__us_1.mp3"}},"muddle":{"media":{"uk":"media/uk/muddle__gb_1.mp3","us":"media/us/muddle__us_1.mp3"},"oxford":{"phon":"ˈmʌdl","pos":"verb","senses":[{"en":"to put things in the wrong order or mix them up","cn":"弄乱；搅混","ex":{"en":"Don't do that—you're muddling my papers.","cn":"别动，你会弄乱我的文件的。"}},{"en":"to confuse somebody","cn":"使困惑；使糊涂","ex":{"en":"Slow down a little—you're muddling me.","cn":"说慢点儿，你都把我搞糊涂了。"}},{"en":"to confuse one person or thing with another","cn":"混淆；搅混；分不清","ex":{"en":"I muddled the dates and arrived a week early.","cn":"我搞错了日期，早到了一个星期。"}},{"en":"a state in which it is difficult to think clearly","cn":"头脑糊涂；思维不清","g":"[countable, usually singular]","ex":{"en":"Can you start from the beginning again—I'm in a muddle.","cn":"请你从头再来一遍吧，我都糊涂了。"},"pos":"noun"},{"en":"a situation in which there is a lack of understanding about arrangements, etc. and things are done wrong","cn":"（局面）一团糟，混乱","g":"[countable, usually singular, uncountable]","ex":{"en":"There was a muddle over the theatre tickets.","cn":"戏票问题搞得一团糟。"},"pos":"noun"},{"en":"a state in which things are untidy and not in order","cn":"凌乱；无序","g":"[countable, usually singular, uncountable]","ex":{"en":"My papers are all in a muddle.","cn":"我的文件混乱不堪。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"糊涂;困惑；混乱状态","en":"If people or things are in a muddle, they are in a state of confusion or disorder.","ex":{"en":"My thoughts are all in a muddle","cn":"我的思维陷入一片混乱。"}},{"pos":"VERB 动词","cn":"搞混;弄乱","en":"If you muddle things or people, you get them mixed up, so that you do not know which is which.","ex":{"en":"Already, one or two critics have begun to muddle the two names","cn":"一两个评论家已经开始把这两个名字弄混了。"}},{"pos":"","cn":"","en":"相关词组：muddle along muddle through muddle up"}]},"examples":[{"en":"They look so alike, I always get them muddled up.","cn":"他们看上去那么像，我总是把他们给搅混了。"},{"en":"Their letters were all muddled up together in a drawer.","cn":"他们的信都乱七八糟地放在一个抽屉里。"}]},"muscle":{"media":{"uk":"media/uk/muscle__gb_1.mp3","us":"media/us/muscle__us_1.mp3"},"oxford":{"phon":"ˈmʌsl","pos":"noun","senses":[{"en":"a piece of body tissue that you make tight and relax in order to move a particular part of the body; the tissue that forms the muscles of the body","cn":"肌肉；肌","g":"[countable, uncountable]","lab":"especially British English","ex":{"en":"a calf/neck/thigh muscle","cn":"小腿／脖颈／大腿肌肉"}},{"en":"physical strength","cn":"体力","g":"[uncountable]","ex":{"en":"He's an intelligent player but lacks the muscle of older competitors.","cn":"他是个聪明的选手，但缺乏老选手的体力。"}},{"en":"the power and influence to make others do what you want","cn":"权力；威信；影响力","g":"[uncountable]","ex":{"en":"to exercise political/industrial/financial muscle","cn":"运用在政治／产业／金融界的影响力"}},{"en":"to move or move something in a particular direction by using your physical strength","cn":"用力移动；用力推动","ex":{"en":"He tried to muscle to the front of the line, but was forced back by security staff.","cn":"他试图挤到队伍前面，但被保安人员强行拉了回来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"肌肉","en":"A muscle is a piece of tissue inside your body which connects two bones and which you use when you make a movement.","ex":{"en":"Keeping your muscles strong and in tone helps you to avoid back problems","cn":"保持肌肉强壮发达有利于预防背部疾病。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"力量;实力;威信","en":"If you say that someone has muscle, you mean that they have power and influence, which enables them to do difficult things.","ex":{"en":"Eisenhower used his muscle to persuade Congress to change the law","cn":"艾森豪威尔用他的影响力说服国会修改了该项法律。"}},{"pos":"PHRASE 短语","cn":"显示实力;小试身手","en":"If a group, organization, or country flexes its muscles, it does something to impress or frighten people, in order to show them that it has power and is considering using it.","ex":{"en":"The Fair Trade Commission has of late been flexing its muscles, cracking down on cases of corruption.","cn":"公平交易委员会最近在显示威力，严厉打击腐败事件。"}},{"pos":"PHRASE 短语","cn":"动一下;动一动","en":"If you say that someone did not move a muscle, you mean that they stayed absolutely still.","ex":{"en":"He stood without moving a muscle, unable to believe what his eyes saw so plainly.","cn":"他站在那里一动不动，不能相信眼前如此清清楚楚看到的一切。"}},{"pos":"","cn":"","en":"相关词组：muscle in"}]},"examples":[{"en":"He's an intelligent player but lacks the muscle of older competitors.","cn":"他是个聪明的选手，但却缺乏老对手的体力。"},{"en":"This exercise will work the muscles of the lower back.","cn":"这样的运动可以锻炼腰部的肌肉。"}]},"municipal":{"media":{"uk":"media/uk/municipal__gb_1.mp3","us":"media/us/municipal__us_1.mp3"},"oxford":{"phon":"mjuːˈnɪsɪpl","pos":"adjective","senses":[{"en":"connected with or belonging to a town, city or district that has its own local government","cn":"市政的；地方政府的","ex":{"en":"municipal elections/councils","cn":"地方政府选举；市政委员会"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"城市的;市政的","en":"Municipal means associated with or belonging to a city or town that has its own local government.","ex":{"en":"The municipal authorities gave the go-ahead for the march.","cn":"市政当局批准了这次游行。"}}]},"examples":[{"en":"the Los Angeles Municipal Art Gallery","cn":"洛杉矶市立美术馆"},{"en":"municipal elections/councils","cn":"地方政府选举；市政委员会"}]},"musically":{"media":{"uk":"media/uk/musically__gb_1.mp3","us":"media/us/musically__us_1.mp3"},"oxford":{"phon":"ˈmjuːzɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with music","cn":"音乐上；在音乐方面","ex":{"en":"musically gifted","cn":"音乐方面有天赋的"}},{"en":"with musical skill","cn":"有音乐技能","ex":{"en":"He plays really musically.","cn":"他的演奏娴熟动听。"}},{"en":"in a way that is pleasant to listen to, like music","cn":"悦耳地；优美动听地；音乐般地","ex":{"en":"to laugh/speak musically","cn":"笑声／讲话悦耳"}}]},"examples":[{"en":"Musically speaking, their latest album is nothing special.","cn":"在音乐方面，他们最新的专辑没什么特别的。"},{"en":"He plays really musically.","cn":"他的演奏娴熟动听。"}]},"musician":{"media":{"uk":"media/uk/musician__gb_1.mp3","us":"media/us/musician__us_1.mp3"},"oxford":{"phon":"mjuˈzɪʃn","pos":"noun","senses":[{"en":"a person who plays a musical instrument or writes music, especially as a job","cn":"音乐家；作曲家；乐师","ex":{"en":"a jazz/rock/classical musician","cn":"爵士乐／摇滚乐乐手；古典音乐家"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"音乐演奏者;音乐家","en":"A musician is a person who plays a musical instrument as their job or hobby.","ex":{"en":"He was a brilliant musician.","cn":"他是一位才华横溢的音乐家。"}}]},"examples":[{"en":"a jazz/rock musician","cn":"爵士乐/摇滚乐乐师"},{"en":"a talented young musician","cn":"有天赋的年轻音乐家"}]},"mute":{"media":{"uk":"media/uk/mute__gb_1.mp3","us":"media/us/mute__us_1.mp3"},"oxford":{"phon":"mjuːt","pos":"adjective","senses":[{"en":"not speaking; not expressed in speech","cn":"沉默的；无声的","ex":{"en":"The child sat mute in the corner of the room.","cn":"这孩子坐在屋子的角落里，一声不吭。"}},{"en":"unable to speak","cn":"哑的","lab":"old-fashioned, offensive，，"},{"en":"the mute button on a phone, television, etc.","cn":"静音按钮","g":"[uncountable]","ex":{"en":"During a phone call, press mute to turn off the microphone.","cn":"在通话过程中，按静音键关闭麦克风。"},"pos":"noun"},{"en":"a device made of metal, rubber or plastic that you use to make the sound of a musical instrument softer","cn":"弱音器","g":"[countable]","lab":"music","pos":"noun"},{"en":"a word for a person who is unable to speak that is now considered offensive","cn":"哑巴","g":"[countable]","lab":"old-fashioned, offensive，，","pos":"noun"},{"en":"to turn off the sound on a phone, television, etc.","cn":"使…静音；把…调成静音","ex":{"en":"A button on the speaker mutes the microphone.","cn":"扬声器上有一个按钮能使麦克风静音。"},"pos":"verb"},{"en":"to make the sound of something, especially a musical instrument, quieter or softer, sometimes using a mute","cn":"消音；减音；减弱（尤指乐器）的声音","ex":{"en":"He muted the strings with his palm.","cn":"他用手掌抹琴弦消音。"},"pos":"verb"},{"en":"to make something weaker or less severe","cn":"减弱；缓解","ex":{"en":"She thought it better to mute her criticism.","cn":"她觉得还是婉转地提出批评比较好。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"缄默的;哑口无言的","en":"Someone who is mute is silent for a particular reason and does not speak.","ex":{"en":"He was mute, distant, and indifferent","cn":"他一句话也不说，显得疏远而冷漠。"}},{"pos":"ADJ 形容词","cn":"哑的;不能说话的","en":"Someone who is mute is unable to speak.","ex":{"en":"Marianna, the duke's daughter, became mute after a shock.","cn":"公爵的女儿玛丽安娜在遭受了一次电击后失声了。"}},{"pos":"VERB 动词","cn":"抑制(情感);减弱，缓和(活动强度)","en":"If someone mutes something such as their feelings or their activities, they reduce the strength or intensity of them.","ex":{"en":"The corruption does not seem to have muted the country's prolonged economic boom.","cn":"腐败似乎没有影响国家经济的持续繁荣。"}},{"pos":"VERB 动词","cn":"降低，减弱(音量)","en":"If you mute a noise or sound, you lower its volume or make it less distinct.","ex":{"en":"They begin to mute their voices, not be as assertive","cn":"他们开始压低嗓门，不再那么肯定了。"}},{"pos":"N-COUNT 可数名词","cn":"（乐器上的）弱音器","en":"A mute is a device which can be used to make a musical instrument produce a quieter, softer sound."}]},"examples":[{"en":"The child sat mute in the corner of the room.","cn":"这孩子坐在屋子的角落里，一声不吭。"},{"en":"She thought it better to mute her criticism.","cn":"她觉得还是婉转地提出批评比较好。"}]},"museums":{"lemma":"museum"},"muskets":{"lemma":"musket"},"muscles":{"lemma":"muscle"},"multiplying":{"lemma":"multiply"},"murdered":{"lemma":"murder"},"mutes":{"lemma":"mute"},"murmured":{"lemma":"murmur"},"mustn't":{"lemma":"must","media":{"uk":"media/ldoce/hwd/bre/e/mustn_t0205.mp3","us":"media/ldoce/hwd/ame/b/ld41mustn_t.mp3"}},"musicians":{"lemma":"musician"},"munich":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"an industrial city in southern Germany, and the capital of the province of Bavaria, whose German name is München. It is known especially for its attractive old buildings and for the beer festival , that takes place there every October.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/p028-000008623.mp3","us":"media/ldoce/hwd/ame/b/p028-000008623.mp3"}},"mug":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马克杯(用来喝热饮的有柄大杯子）","en":"A mug is a large deep cup with straight sides and a handle, used for hot drinks.","ex":{"en":"He spooned instant coffee into two of the mugs.","cn":"他用勺子把速溶咖啡舀入两个杯子中。"}},{"pos":"VERB 动词","cn":"对…行凶抢劫","en":"If someone mugs you, they attack you in order to steal your money.","ex":{"en":"I was walking out to my car when this guy tried to mug me","cn":"我正出门朝我的车走去，就在这时这家伙企图对我进行抢劫。"}},{"pos":"N-COUNT 可数名词","cn":"傻瓜;易受骗者","en":"If you say that someone is a mug, you mean that they are stupid and easily deceived by other people.","ex":{"en":"He's a mug as far as women are concerned","cn":"在女性眼里，他是个傻瓜。"}},{"pos":"PHRASE 短语","cn":"(不值得一做的)傻瓜的游戏，傻事","en":"If you say that an activity is a mug's game, you mean that it is not worth doing because it does not give the person who is doing it any benefit or satisfaction.","ex":{"en":"I used to be a very heavy gambler, but not any more. It's a mug's game","cn":"我曾经是个赌棍，但现在再也不赌了，那是傻瓜的游戏。"}},{"pos":"N-COUNT 可数名词","cn":"脸;面孔","en":"Some-one's mug is their face.","ex":{"en":"He managed to get his ugly mug on the telly.","cn":"他设法让自己那张丑陋的脸上了电视。"}},{"pos":"","cn":"","en":"相关词组：mug up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is tricked by someone else, especially so that they become involved in the other person's dishonest plans without realizing it","cn":""},{"en":"someone who believes everything they are told, even when it is clearly not true","cn":""},{"en":"someone who is easily deceived, especially so that they do much more or give much more than is fair or reasonable","cn":""}]},"collocations":{"phrases":["ADJ. large | empty | chipped, cracked | hot, steaming a hot mug of tea | beer, coffee | pint | commemorative, souvenir | shaving | china, pl","VERB + MUG fill, pour (out) She filled her mug with orange juice. He poured a mug of tea. | pour (sb) out Craig got up and poured himself a ","PHRASES a mug of beer/coffee/tea, the rim of a mug He ran his finger around the rim of the mug."]},"media":{"img":["media/ldoce/img/mug.jpg","media/thumb/mug.jpg"],"uk":"media/ldoce/hwd/bre/5/brelasdemug.mp3","us":"media/ldoce/hwd/ame/7/mug1.mp3"},"examples":[{"en":"I never want to see his ugly mug again.","cn":"我再也不想看到他那张丑恶的面孔。"},{"en":"She had been mugged in the street in broad daylight.","cn":"光天化日之下，她在街上遭到抢劫。"}],"oxford":{"phon":"mʌɡ","pos":"noun","senses":[{"en":"a tall cup for drinking from, usually with straight sides and a handle, used without a saucer","cn":"大杯；缸子；马克杯","ex":{"en":"a coffee mug","cn":"大咖啡杯"}},{"en":"a mug and what it contains","cn":"一缸子（的量）","ex":{"en":"He drank a mug of coffee and left.","cn":"他喝了一大杯咖啡后就离开了。"}},{"en":"a person’s face","cn":"（人的）脸","lab":"slang","ex":{"en":"I never want to see his ugly mug again.","cn":"我再也不想看到他那张丑恶的面孔。"}},{"en":"a person who is stupid and easy to trick","cn":"傻瓜；笨蛋","lab":"informal","ex":{"en":"They made me look a complete mug.","cn":"他们弄得我像个十足的傻瓜。"}},{"en":"to attack somebody violently in order to steal their money, jewellery, etc., especially in a public place","cn":"（公然）行凶抢劫，打劫","g":"[transitive]","ex":{"en":"She had been mugged in the street in broad daylight.","cn":"光天化日之下，她在街上遭到抢劫。"},"pos":"verb"},{"en":"to make silly expressions with your face or behave in a silly, exaggerated way, especially on the stage or before a camera","cn":"（尤指在舞台上或摄影机前）扮鬼脸，扮怪相","g":"[intransitive]","lab":"informal","ex":{"en":"to mug for the cameras","cn":"在摄影机前扮怪相"},"pos":"verb"}]}},"mum":{"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"妈妈","en":"Your mum is your mother.","ex":{"en":"He misses his mum","cn":"他想念他的妈妈。"}},{"pos":"PHRASE 短语","cn":"保守秘密;闭口不谈","en":"If you keep mum or stay mum about something, you do not tell anyone about it.","ex":{"en":"He is keeping mum about his feelings on the matter.","cn":"他闭口不谈他对此事的个人感受。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a female parent","cn":""},{"en":"used when talking to your father, or about someone’s father","cn":""},{"en":"a name for mother, which is used especially by young children or when you are talking to young children","cn":""}]},"collocations":{"phrases":["ADJ. young | single, unmarried | career, working | proud | expectant, pregnant (also mum-to-be ) | new The group is aimed at new mums with y","PHRASES mum and dad"]},"media":{"uk":"media/ldoce/hwd/bre/9/mum_n0205.mp3","us":"media/ldoce/hwd/ame/7/mum1.mp3"},"examples":[{"en":"A lot of mums and dads have the same worries.","cn":"许多父母都有同样的担忧。"},{"en":"He kept mum about what he'd seen.","cn":"他对他所看到的只字不说。"}],"oxford":{"phon":"mʌm","pos":"noun","senses":[{"en":"a mother","cn":"妈妈","ex":{"en":"Call your mum.","cn":"打电话给你妈妈。"}}]}},"mustard":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"芥子酱;芥子泥","en":"Mustard is a yellow or brown paste usually eaten with meat. It tastes hot and spicy.","ex":{"en":"...a pot of mustard","cn":"一罐芥子酱"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(果实可做芥子泥的)芥菜花;芥菜","en":"Mustard is a small plant with yellow flowers. The seeds can be used to make mustard."},{"pos":"COLOUR 颜色词","cn":"芥末色;暗黄色","en":"Mustard is used to describe things that are brownish yellow in colour.","ex":{"en":"...a mustard coloured jumper.","cn":"暗黄色的羊毛衫"}},{"pos":"PHRASE 短语","cn":"如所期待的那么好；符合要求","en":"If someone does not cut the mustard, their work or their performance is not as good as it should be or as good as it is expected to be."},{"pos":"PHRASE 短语","cn":"非常渴望;非常热情","en":"If you are as keen as mustard or mustard keen, you are very eager or enthusiastic.","ex":{"en":"I have a pupil who scored very low in assessments but is keen as mustard.","cn":"我有一个学生，考评得分很低，但学习热情十足。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a yellow sauce with a strong taste, eaten especially with meat","cn":"芥末酱"},{"en":"a plant with yellow flowers and seeds that are used to make mustard sauce","cn":"芥菜"},{"en":"a yellow-brown colour","cn":"芥末黄﹐深黄色"}]},"collocations":{"phrases":["ADJ. hot Add some hot English mustard. | mild | wholegrain | Dijon, English, French","VERB + MUSTARD spread (sth with) Spread the bread thinly with mustard. | add, mix (sth with) Mix together the mustard and olive oil. | eat s","MUSTARD + NOUN seed | powder | sauce | colour •"]},"media":{"uk":"media/ldoce/hwd/bre/7/mustard0205.mp3","us":"media/ldoce/hwd/ame/7/mustard.mp3"},"examples":[{"en":"I didn't cut the mustard as a hockey player.","cn":"我不是一个合格的曲棍球手。"},{"en":"mustard and cress (= leaves of white mustard grown with cress )","cn":"芥菜叶和水芹"}],"oxford":{"phon":"ˈmʌstəd","pos":"adjective","senses":[{"en":"between yellow and brown in colour","cn":"芥末黄；褐黄色","ex":{"en":"a mustard sweater","cn":"芥末黄毛线衣"}},{"en":"a thick cold yellow or brown sauce, made from the seeds of some mustard plants, that tastes hot and spicy and is usually eaten with meat","cn":"芥末酱","ex":{"en":"a jar of mustard","cn":"一罐芥末酱"},"pos":"noun"},{"en":"a small plant with yellow flowers, grown for its seeds that are used to make mustard","cn":"芥；芥菜","pos":"noun"},{"en":"the leaves of the mustard plant that are eaten raw in salads","cn":"芥菜叶","lab":"British English","ex":{"en":"mustard and cress (= leaves of white mustard grown with cress)","cn":"芥菜叶和水芹"},"pos":"noun"},{"en":"a colour between yellow and brown","cn":"芥末黄；棕黄色","pos":"noun"}]}},"mundane":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"普通的;平凡的;单调的","en":"Something that is mundane is very ordinary and not at all interesting or unusual.","ex":{"en":"Be willing to do even mundane tasks.","cn":"即使平凡的工作也乐意承担。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not interesting in any way","cn":""},{"en":"very ordinary and therefore rather boring. People often use this phrase in everyday English, instead of saying directly that something is boring","cn":""},{"en":"boring","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"An ordinary, unexciting thing can be called mundane : \"Superman hid his heroic feats by posing as his mundane alter ego, Clark Kent.\""}]},"collocations":{"phrases":["VERBS be, seem, sound | become | find sth I found the job very mundane","ADV. very | thoroughly, utterly | fairly, pretty, rather, somewhat a rather mundane task | apparently"]},"media":{"uk":"media/ldoce/hwd/bre/3/mundane0205.mp3","us":"media/ldoce/hwd/ame/b/mundane.mp3"},"examples":[{"en":"On a more mundane level, can we talk about the timetable for next week?","cn":"说点儿实际的吧，我们能谈谈下周的时间安排吗？"},{"en":"I lead a pretty mundane existence.","cn":"我过着相当平淡的生活。"}],"oxford":{"phon":"mʌnˈdeɪn","pos":"adjective","senses":[{"en":"not interesting or exciting","cn":"平淡无奇的；枯燥乏味的","ex":{"en":"a mundane task/job","cn":"单调的任务"}}]}},"mutter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"轻声说话;小声抱怨","en":"If you mutter, you speak very quietly so that you cannot easily be heard, often because you are complaining about something.","ex":{"en":"'God knows what's happening in that madman's mind,' she muttered","cn":"她咕哝着：“天知道那个疯子在想什么。”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you mutter , you mumble under your breath, often in an angry way. You might mutter to yourself as you clean graffiti off your garage, for example."}]},"collocations":{"phrases":["ADV. gruffly, harshly, hoarsely, huskily, thickly, through clenched/gritted teeth &lsquo;I don't need a drink, &rsquo; she muttered through ","VERB + MUTTER be heard to, hear sb A number of non-British visitors were heard to mutter that it would not have happened in Frankfurt. She h","PREP. about muttering about the incompetence of the office staff | to muttering incoherently to himself"]},"media":{"uk":"media/ldoce/hwd/bre/0/mutter0205.mp3","us":"media/ldoce/hwd/ame/2/mutter.mp3"},"examples":[{"en":"‘How dare she,’ he muttered under his breath.","cn":"他轻声嘀咕道：“她怎么敢。”"},{"en":"She just sat there muttering to herself.","cn":"她坐在那儿独自唧唧咕咕的。"}],"oxford":{"phon":"ˈmʌtə(r)","pos":"verb","senses":[{"en":"to speak or say something in a quiet voice that is difficult to hear, especially because you are annoyed about something","cn":"嘀咕；嘟囔","g":"[transitive, intransitive]","ex":{"en":"‘How dare she,’ he muttered under his breath.","cn":"他轻声嘀咕道：“她怎么敢。”"}},{"en":"to complain about something, without saying publicly what you think","cn":"（私下）抱怨，发牢骚","g":"[intransitive, transitive]","ex":{"en":"Workers continued to mutter about the management.","cn":"工人私下对资方还是有怨言。"}},{"en":"a quiet sound or words that are difficult to hear","cn":"嘀咕；嘟哝；低语声","ex":{"en":"the soft mutter of voices","cn":"柔和的低语声"},"pos":"noun"}]}},"mural":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"壁画","en":"A mural is a picture painted on a wall.","ex":{"en":"...a mural of Tangier bay.","cn":"描绘丹吉尔湾的壁画"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a painting that is painted on a wall, either inside or outside a building","cn":"壁画"}]},"vocab":{"pos":"n adj","senses":[{"en":"A mural is a large-scale painting usually done on a wall. Diego Rivera, the Mexican muralist , is famous for the plaster murals he painted on the walls at Rockefeller Center in the 1930s."}]},"collocations":{"phrases":["ADJ. giant, huge, large-scale | painted","VERB + MURAL create, produce | paint | design","MURAL + VERB depict sth, show sth murals depicting Aesop's fables"]},"media":{"uk":"media/ldoce/hwd/bre/d/mural0205.mp3","us":"media/ldoce/hwd/ame/f/mural.mp3"},"examples":[{"en":"mural paintings","cn":"壁画"}],"oxford":{"phon":"ˈmjʊərəl","pos":"adjective","senses":[{"en":"large and done on a wall, sometimes on an outside wall of a building","cn":"壁画","ex":{"en":"mural paintings","cn":"壁画"}},{"en":"a painting, usually a large one, done on a wall, sometimes on an outside wall of a building","cn":"壁画","ex":{"en":"murals depicting Aesop’s fables","cn":"讲述《伊索寓言》的壁画"},"pos":"noun"}]}},"mushroom":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"蘑菇;伞菌;蕈","en":"Mushrooms are fungi that you can eat.","ex":{"en":"There are many types of wild mushrooms.","cn":"野生蘑菇有很多种。"}},{"pos":"VERB 动词","cn":"迅速成长;大量涌现","en":"If something such as an industry or a place mushrooms, it grows or comes into existence very quickly.","ex":{"en":"The media training industry has mushroomed over the past decade","cn":"在过去10年里，媒体培训产业迅速成长。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of several kinds of fungus with stems and round tops, some of which can be eaten","cn":"蘑菇"},{"en":"to grow and develop very quickly","cn":"快速成长﹐迅速发展"}]},"collocations":{"phrases":["ADJ. edible | poisonous | cultivated | wild | button, chestnut, field, oyster, porcini, shiitake | dried | hallucinogenic, magic, psychedeli","VERB + MUSHROOM eat, have I'll have the garlic mushrooms for a starter. | cultivate, grow | pick They went into the woods to pick wild mushr","MUSHROOM + NOUN compost | omelette, sauce, soup | cloud •"]},"media":{"img":["media/ldoce/img/mushroom.jpg","media/thumb/mushroom.jpg"],"uk":"media/ldoce/hwd/bre/8/mushroom_v0205.mp3","us":"media/ldoce/hwd/ame/7/mushroom1.mp3"},"examples":[{"en":"We expect the market to mushroom in the next two years.","cn":"我们期望未来两年内市场会迅速发展。"},{"en":"a field mushroom (= the most common type that is eaten, often just called a ‘mushroom’, and often grown to be sold)","cn":"洋蘑菇"}],"oxford":{"phon":"ˈmʌʃrʊm","pos":"noun","senses":[{"en":"a fungus with a round flat head and short stem. Many mushrooms can be eaten.","cn":"蘑菇；蕈；伞菌","ex":{"en":"a field mushroom (= the most common type that is eaten, often just called a ‘mushroom’, and often grown to be sold)","cn":"洋蘑菇"}},{"en":"to rapidly grow or increase in number","cn":"快速生长；迅速增长","g":"[intransitive]","ex":{"en":"We expect the market to mushroom in the next two years.","cn":"我们期望未来两年内市场会迅速发展。"},"pos":"verb"},{"en":"to gather mushrooms in a field or wood","cn":"采蘑菇","g":"[intransitive]","pos":"verb"}]}},"mumps":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"腮腺炎","en":"Mumps is a disease usually caught by children. It causes a mild fever and painful swelling of the glands in the neck."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an infectious illness which makes your neck swell and become painful","cn":"腮腺炎"}]},"media":{"uk":"media/ldoce/hwd/bre/7/mumps0205.mp3","us":"media/ldoce/hwd/ame/e/mumps.mp3"},"examples":[{"en":"Mumps is quite serious if you get it as an adult.","cn":"成年人如果得了腮腺炎会很严重。"}],"oxford":{"phon":"mʌmps","pos":"noun","senses":[{"en":"a disease, especially of children, that causes painful swellings at the sides of the face and under the ears","cn":"腮腺炎"}]}},"mutiny":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(通常指士兵或水手的)反叛，哗变，暴动","en":"A mutiny is a refusal by people, usually soldiers or sailors, to continue obeying a person in authority.","ex":{"en":"A series of coup attempts and mutinies within the armed forces destabilized the regime","cn":"军队内部一连串的政变图谋和暴动动摇了该政权。"}},{"pos":"VERB 动词","cn":"(通常指士兵或水手)反叛，哗变，暴动","en":"If a group of people, usually soldiers or sailors, mutiny, they refuse to continue obeying a person in authority.","ex":{"en":"Units stationed around the capital mutinied because they had received no pay for nine months","cn":"驻扎在首府周边的部队因9个月没有领到军饷而哗变。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to take part in an attempt, especially one that continues only for a short time, to change the government using violence","cn":""},{"en":"if people rise up , large numbers of them begin violently to oppose their government or other authority, especially without planning to do this","cn":""},{"en":"if a group in the army or navy mutiny , they try to take power from their officers by refusing to obey their orders and using violence","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A mutiny is a rebellion against authority, like when sailors overthrow the captain of a ship or when a class of 8th graders refuses to dissect a frog in biology class."}]},"collocations":{"phrases":["ADJ. army, prison | military","VERB + MUTINY lead | be faced with, face","PREP. ~ against He led a military mutiny against the senior generals. | ~ by mutiny by the men • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/c/mutiny0205.mp3","us":"media/ldoce/hwd/ame/d/mutiny.mp3"},"examples":[{"en":"Discontent among the ship's crew finally led to the outbreak of mutiny.","cn":"船员的不满情绪最终酿成了暴乱。"},{"en":"We have a family mutiny on our hands!","cn":"我们家出了叛逆之事，需要处理！"}],"oxford":{"phon":"ˈmjuːtəni","pos":"noun","senses":[{"en":"the act of refusing to obey the orders of somebody in authority, especially by soldiers or sailors","cn":"（尤指士兵或船员的）哗变，暴动","ex":{"en":"Discontent among the ship's crew finally led to the outbreak of mutiny.","cn":"船员的不满情绪最终酿成了暴乱。"}},{"en":"to refuse to obey the orders of somebody in authority","cn":"不服从；反抗；反叛","ex":{"en":"There was a real chance the crew would mutiny.","cn":"全体船员真有可能暴动。"},"pos":"verb"}]}},"mumble":{"collins":{"senses":[{"pos":"VERB 动词","cn":"咕哝;含糊地说","en":"If you mumble, you speak very quietly and not at all clearly with the result that the words are difficult to understand.","ex":{"en":"Her grandmother mumbled in her sleep","cn":"她祖母含混不清地说着梦话。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To mumble is to talk quietly and indistinctly. When people speak in a mumble , it's hard to understand them."}]},"collocations":{"phrases":["ADV. incoherently | drowsily, sleepily","PREP. about I couldn't understand what he was mumbling about. | into She mumbled something into her pillow. | to George mumbled incoherently"]},"media":{"uk":"media/ldoce/hwd/bre/a/mumble0205.mp3","us":"media/ldoce/hwd/ame/7/mumble.mp3"},"examples":[{"en":"They tried to make sense of her mumblings.","cn":"他们试图弄明白她在嘟哝些什么。"},{"en":"‘Sorry,’ she mumbled.","cn":"她含含糊糊地说：“对不起。”"}],"oxford":{"phon":"ˈmʌmbl","pos":"verb","senses":[{"en":"to speak or say something in a quiet voice in a way that is not clear","cn":"嘟哝；口齿不清地说","ex":{"en":"I could hear him mumbling to himself.","cn":"我听到他在喃喃自语。"}},{"en":"speech or words that are spoken in a quiet voice in a way that is not clear","cn":"喃喃自语；嘟哝","ex":{"en":"He spoke in a low mumble, as if to himself.","cn":"他自言自语般地嘟哝着。"},"pos":"noun"}]}},"mutilate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使残缺不全;使受到严重损伤","en":"If a person or animal is mutilated, their body is severely damaged, usually by someone who physically attacks them.","ex":{"en":"More than 30 horses have been mutilated in the last nine months","cn":"在过去9个月里，超过30匹马受了重伤。"}},{"pos":"VERB 动词","cn":"(故意)毁坏，破坏","en":"If something is mutilated, it is deliberately damaged or spoiled.","ex":{"en":"Brecht's verdict was that his screenplay had been mutilated","cn":"布雷赫特的结论是他的电影剧本已被窜改。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to severely and violently damage someone’s body, especially by cutting or removing part of it","cn":"残害〔某人的身体〕﹐使断肢﹐使伤残"},{"en":"to damage or change something so much that it is completely spoiled","cn":"完全损毁﹔使面目全非"}]},"vocab":{"pos":"v","senses":[{"en":"Mutilate is a verb that means to injure or ruin, usually in a brutal or messy way. If you drop a cantaloupe into a wood chipper, you'll mutilate that poor melon, with chunks of fruit and rind flying everywhere."}]},"collocations":{"phrases":["ADV. badly, horribly, severely, terribly A lot of the bodies had been badly mutilated."]},"media":{"uk":"media/ldoce/hwd/bre/7/mutilate0205.mp3","us":"media/ldoce/hwd/ame/c/mutilate.mp3"},"examples":[{"en":"Thousands suffered death or mutilation in the bomb blast.","cn":"在炸弹爆炸事件中，数千人被炸死，或成为残废。"},{"en":"Intruders slashed and mutilated several paintings.","cn":"闯进来的人毁坏了好几幅油画。"}],"oxford":{"phon":"ˈmjuːtɪleɪt","pos":"verb","senses":[{"en":"to damage somebody’s body very severely, especially by cutting or tearing off part of it","cn":"使残废；使残缺不全；毁伤","ex":{"en":"The body had been badly mutilated.","cn":"尸体被严重毁伤。"}},{"en":"to damage something very badly","cn":"严重损毁；毁坏","ex":{"en":"Intruders slashed and mutilated several paintings.","cn":"闯进来的人毁坏了好几幅油画。"}}]}},"muddled":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困惑的;糊涂的","en":"If someone is muddled, they are confused about something.","ex":{"en":"I'm afraid I'm a little muddled. I'm not exactly sure where to begin.","cn":"恐怕我有点糊涂了，我不确定该从何处着手。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having more than one possible meaning and therefore confusing and unclear","cn":""},{"en":"words or statements that are imprecise are unclear because they do not describe or explain something in an exact way when this is necessary","cn":""},{"en":"unclear, especially because not enough details are given","cn":""}]},"collocations":{"phrases":["VERBS be, feel | become, get","ADV. extremely, hopelessly, very | a bit, rather, slightly, somewhat Her ideas are slightly muddled.","PHRASES be/get muddled up"]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41muddled.mp3","us":"media/ldoce/hwd/ame/5/laadmuddled.mp3"},"examples":[{"en":"He gets muddled when the teacher starts shouting.","cn":"老师一喊叫他就心烦意乱。"},{"en":"muddled thinking","cn":"混乱的思想"}],"oxford":{"phon":"ˈmʌdld","pos":"adjective","senses":[{"en":"confused","cn":"糊涂的；困惑的；混乱的","ex":{"en":"He gets muddled when the teacher starts shouting.","cn":"老师一喊叫他就心烦意乱。"}}]},"base":"muddle"},"murderer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谋杀者;杀人犯","en":"A murderer is a person who has murdered someone.","ex":{"en":"One of these men may have been the murderer.","cn":"他们其中有一个人可能是杀人凶手。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who steals things","cn":""},{"en":"someone who steals money or valuable things from a bank, shop etc – used especially when someone sees the person who is stealing","cn":""},{"en":"someone who goes into people’s homes in order to steal","cn":""}]},"collocations":{"phrases":["ADJ. alleged | convicted | mass, multiple, serial | real He protested his innocence and promised to help police track down the real murderer","VERB + MURDERER hunt, track down | catch, find, reveal (sb as), uncover","MURDERER + VERB strike The murderer has struck again. | kill sb","PHRASES the identity of the murderer The identity of her murderer has not yet been revealed."]},"media":{"uk":"media/ldoce/hwd/bre/f/murderer0205.mp3","us":"media/ldoce/hwd/ame/b/laadmurderer.mp3"},"examples":[{"en":"a mass murderer (= who has killed a lot of people)","cn":"杀死很多人的凶手"},{"en":"a convicted murderer","cn":"被判有罪的谋杀犯"}],"oxford":{"phon":"ˈmɜːdərə(r)","pos":"noun","senses":[{"en":"a person who has killed somebody deliberately and illegally","cn":"杀人犯；杀人凶手","ex":{"en":"A convicted murderer was on the run last night.","cn":"昨晚，一名被定罪的杀人犯在逃。"}}]}},"multinational":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(公司)多国的，跨国经营的","en":"A multinational company has branches or owns companies in many different countries.","ex":{"en":"...multinationals such as Ford and IBM.","cn":"福特公司和IBM公司等跨国公司"}},{"pos":"ADJ 形容词","cn":"(军队、组织或团体)人员来自不同国家的，国际的","en":"Multinational armies, organizations, or other groups involve people from several different countries.","ex":{"en":"The US troops would be part of a multinational force.","cn":"美军将是多国部队的一个组成部分。"}},{"pos":"ADJ 形容词","cn":"(国家或地区)多民族的","en":"Multinational countries or regions have a population that is made up of people of several different nationalities."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a very large company that has offices or factories in many different countries","cn":""},{"en":"a large company that employs a lot of people, especially one that includes several smaller companies","cn":""},{"en":"a very large business organization that consists of several different companies which have joined together","cn":""}]},"collocations":{"phrases":["ADJ. big, giant, large | leading, major | foreign","MULTINATIONAL + VERB operate foreign multinationals operating in the UK"]},"media":{"uk":"media/ldoce/hwd/bre/b/multinational_0205.mp3","us":"media/ldoce/hwd/ame/8/multinational.mp3"},"examples":[{"en":"A multinational force is being sent to the trouble spot.","cn":"一支多国部队正赶往多事的地区。"},{"en":"multinational companies/corporations","cn":"跨国公司"}],"oxford":{"phon":"ˌmʌltiˈnæʃnəl","pos":"adjective","senses":[{"en":"existing in or involving many countries","cn":"跨国的；涉及多国的","ex":{"en":"multinational companies/corporations","cn":"跨国公司"}},{"en":"a company that operates in several different countries, especially a large and powerful company","cn":"跨国公司","ex":{"en":"The country’s industry is largely controlled by the multinationals.","cn":"这国家的工业在很大程度上被众多跨国公司控制着。"},"pos":"noun"}]}},"muddy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沾满泥的;多泥的;泥泞的","en":"Something that is muddy contains mud or is covered in mud.","ex":{"en":"...a muddy track","cn":"泥泞的小道"}},{"pos":"VERB 动词","cn":"使沾上泥","en":"If you muddy something, you cause it to be muddy.","ex":{"en":"The ground still smelled of rain and they muddied their shoes","cn":"地面还散发着雨后的气息，他们把鞋上弄得全是泥。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暗褐色的;土黄色的","en":"Muddy is used to describe a colour which is dull and brownish.","ex":{"en":"The paper has turned a muddy colour.","cn":"报纸已变成土黄色了。"}},{"pos":"VERB 动词","cn":"使更为复杂;使难以理解","en":"If someone or something muddies a situation or issue, they cause it to seem less clear and less easy to understand.","ex":{"en":"It's difficult enough without muddying the issue with religion.","cn":"即使不把宗教牵扯进去，这个问题也已经够棘手的了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not clean","cn":""},{"en":"very dirty","cn":""},{"en":"covered with mud","cn":""}]},"vocab":{"pos":"adj v","senses":[{"en":"Muddy is a verb that means to make dirty with mud. You might muddy up your mom's white shag rug if you don't take off your dirty hiking boots before you walk inside."}]},"collocations":{"phrases":["VERBS be, look | become, get | get sth, make sth Don't get your shoes muddy! The rain had made the football pitch extremely muddy.","ADV. extremely, very | all My boots were all muddy. | a bit, rather We all got a bit muddy and wet."]},"media":{"uk":"media/ldoce/hwd/bre/0/muddy_v0205.mp3","us":"media/ldoce/hwd/ame/1/muddy1.mp3"},"examples":[{"en":"muddy boots/knees","cn":"沾满泥浆的靴子/膝盖"},{"en":"a muddy field/track","cn":"泥泞的田野/小径"}],"oxford":{"phon":"ˈmʌdi","pos":"adjective","senses":[{"en":"full of or covered in mud","cn":"多泥的；泥泞的","ex":{"en":"a muddy field/track","cn":"泥泞的田野／小径"}},{"en":"containing mud; not clear","cn":"含泥的；浑浊的","ex":{"en":"muddy water","cn":"泥水"}},{"en":"not clear or bright","cn":"灰暗的；暗淡的","ex":{"en":"muddy green/brown","cn":"暗绿色；暗褐色"}},{"en":"to make something muddy","cn":"使变得泥泞；使浑浊","ex":{"en":"She had muddied her white dress.","cn":"她弄脏了她的白色裙子。"},"pos":"verb"}]}},"multiply":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)成倍地增加;(使)大量地增加","en":"When something multiplies or when you multiply it, it increases greatly in number or amount.","ex":{"en":"Such disputes multiplied in the eighteenth and nineteenth centuries","cn":"这类纠纷在18和19世纪大量增多。"}},{"pos":"VERB 动词","cn":"繁殖;滋生","en":"When animals and insects multiply, they increase in number by giving birth to large numbers of young.","ex":{"en":"These creatures can multiply quickly.","cn":"这些动物能迅速繁殖。"}},{"pos":"VERB 动词","cn":"乘;使相乘","en":"If you multiply one number by another, you add the first number to itself as many times as is indicated by the second number. For example 2 multiplied by 3 is equal to 6.","ex":{"en":"What do you get if you multiply six by nine?","cn":"9乘以6得多少？"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put two or more numbers together to find the total","cn":""},{"en":"to reduce one number by another number. take something away sounds more informal than subtract","cn":""},{"en":"to add a number to itself a particular number of times","cn":""}]},"collocations":{"phrases":["ADV. fourfold, fivefold, manifold, etc. Just imagine all the problems we've been having, multiplied a thousandfold. | endlessly, indefinitel","PREP. by 2 multiplied by 4 makes 8 (= 2亊4 8)"]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdemultiply.mp3","us":"media/ldoce/hwd/ame/3/multiply.mp3"},"examples":[{"en":"It is possible to multiply these bacteria in the laboratory.","cn":"在实验室里繁殖这些细菌是可以做到的。"},{"en":"The children are already learning to multiply and divide.","cn":"孩子们已经开始学习乘法和除法了。"}],"oxford":{"phon":"ˈmʌltɪplaɪ","pos":"verb","senses":[{"en":"to add a number to itself a particular number of times","cn":"乘；乘以","g":"[intransitive, transitive]","ex":{"en":"The children are already learning to multiply and divide.","cn":"孩子们已经开始学习乘法和除法了。"}},{"en":"to increase or make something increase very much in number or amount","cn":"大量增加；成倍增加","g":"[intransitive, transitive]","ex":{"en":"Our problems have multiplied since last year.","cn":"自去年以来，我们的问题成倍增加。"}},{"en":"to produce young animals, bacteria, etc. in large numbers","cn":"繁殖；增殖","g":"[intransitive, transitive]","lab":"biology","ex":{"en":"Rabbits multiply rapidly.","cn":"兔子繁殖迅速。"}}]}},"mule":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骡;骡子","en":"A mule is an animal whose parents are a horse and a donkey."},{"pos":"N-COUNT 可数名词","cn":"拖鞋式便鞋;拖鞋","en":"A mule is a shoe or slipper which is open around the heel."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an animal that has a donkey and a horse as parents","cn":"骡﹐骡子"},{"en":"someone who brings illegal drugs into a country by hiding them on or in their body","cn":"骡子〔把毒品藏在身上或体内带进某国的人〕"},{"en":"a woman’s shoe or slipper that covers the front part of the foot but has no material around the heel","cn":"拖鞋式女鞋"}]},"collocations":{"phrases":["ADJ. pack","QUANT. team","VERB + MULE ride (on) | drive | saddle","MULE + VERB bray | carry sth","PREP. by ~ They travelled across the mountains by mule. | on a/the ~ a man on a mule"]},"media":{"uk":"media/ldoce/hwd/bre/b/mule0205.mp3","us":"media/ldoce/hwd/ame/0/mule1.mp3","img":["media/thumb/mule.jpg"]},"examples":[{"en":"He's as stubborn as a mule.","cn":"他像骡子一样倔。"}],"oxford":{"phon":"mjuːl","pos":"noun","senses":[{"en":"an animal that has a female horse and a male donkey as parents, used especially for carrying loads","cn":"骡子","ex":{"en":"He's as stubborn as a mule.","cn":"他像骡子一样倔。"}},{"en":"a person who is paid to take drugs illegally from one country to another","cn":"越境运毒者","lab":"slang","ex":{"en":"a drug/drugs mule","cn":"偷运毒品者"}},{"en":"a slipper (= a soft shoe for wearing indoors) or a woman's shoe that is open around the heel","cn":"穆勒鞋（跟部敞开）"}]}},"mucus":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(人体分泌的)黏液","en":"Mucus is a thick liquid that is produced in some parts of your body, for example the inside of your nose."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thick liquid produced in parts of your body such as your nose 〔","cn":"人体分泌的〕黏液〔如鼻涕〕"}]},"vocab":{"pos":"n","senses":[{"en":"Mucus is snot and other slime from inside your body. More specifically, mucus is a secretion of your body's mucus membranes that lubricates the inside of your body and helps protect you from bacteria. You’re welcome."}]},"collocations":{"phrases":["ADJ. copious, excess | cervical, nasal | sticky, stringy, thick, thin","VERB + MUCUS produce, secrete","MUCUS + NOUN discharge, production, secretion"]},"media":{"uk":"media/ldoce/hwd/bre/8/mucus0205.mp3","us":"media/ldoce/hwd/ame/d/mucus.mp3"},"examples":[{"en":"mucous glands","cn":"分泌黏液的腺体"}],"oxford":{"phon":"ˈmjuːkəs","pos":"noun","senses":[{"en":"a thick liquid that is produced in parts of the body, such as the nose, by a mucous membrane","cn":"黏液；鼻涕","ex":{"en":"a handkerchief stained with blood and mucus","cn":"沾有血和粘液的手帕"}}]}},"multi-user":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"multi-user computer systems or software can be used by more than one person at the same time 〔","cn":"计算机系统或软件〕可多人同时使用的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ldoce6multi_user.mp3","us":"media/ldoce/hwd/ame/7/ldoce6multi_user.mp3"},"examples":[{"en":"a multi-user software licence","cn":"多用户共享软件许可"}],"oxford":{"phon":"ˌmʌlti ˈjuːzə(r)","pos":"adjective","senses":[{"en":"able to be used by more than one person at the same time","cn":"多用户（共享）的","ex":{"en":"a multi-user software licence","cn":"多用户共享软件许可"}}]}}});
